import heapq

def top_of_book(updates):
    """updates: [side, price, qty]; side 0 = bid, 1 = ask; qty 0 deletes the level. Returns after each update
    [best_bid, bid_qty, best_ask, ask_qty] with -1 for an empty side."""
    lv = [{}, {}]; hp = [[], []]; out = []
    for side, px, q in updates:
        if q == 0: lv[side].pop(px, None)
        else:
            if px not in lv[side]: heapq.heappush(hp[side], -px if side == 0 else px)
            lv[side][px] = q
        row = []
        for s in (0, 1):
            h = hp[s]
            while h and ((-h[0] if s == 0 else h[0]) not in lv[s]): heapq.heappop(h)
            if h:
                best = -h[0] if s == 0 else h[0]; row += [best, lv[s][best]]
            else: row += [-1, -1]
        out.append(row)
    return out

