vector<vector<int>> topOfBook(vector<vector<int>>& u) {
    map<int,int,greater<int>> bids; map<int,int> asks; vector<vector<int>> out;
    for (auto& x : u) { int side = x[0], px = x[1], q = x[2];
        if (side == 0) { if (q) bids[px] = q; else bids.erase(px); } else { if (q) asks[px] = q; else asks.erase(px); }
        vector<int> row; if (bids.empty()) { row.push_back(-1); row.push_back(-1); } else { row.push_back(bids.begin()->first); row.push_back(bids.begin()->second); }
        if (asks.empty()) { row.push_back(-1); row.push_back(-1); } else { row.push_back(asks.begin()->first); row.push_back(asks.begin()->second); }
        out.push_back(row); }
    return out;
}
